// Cross-language-comparable benchmark: reads the SHARED corpora from
// bench/corpus/ (generated by bench/gen_corpus.py) so C++, Haskell and Python
// all measure byte-identical inputs. Prints ns/leaf per strategy.
//
// Usage: ./build/corpus_bench [corpus_dir]   (default: bench/corpus)
#include "parser/evaluator.hpp"

#include <algorithm>
#include <chrono>
#include <fstream>
#include <limits>
#include <print>
#include <string>
#include <vector>

using namespace mp;
using Clock = std::chrono::steady_clock;

namespace {
volatile double g_sink = 0;
const std::vector<int> kSizes = {10, 100, 1000, 10000};

std::vector<std::string> load(const std::string& dir, int n) {
    std::vector<std::string> out;
    std::ifstream f(dir + "/n" + std::to_string(n) + ".txt");
    std::string line;
    while (std::getline(f, line))
        if (!line.empty()) out.push_back(line);
    return out;
}

double timeNs(auto f) {
    const auto t0 = Clock::now();
    f();
    return std::chrono::duration<double, std::nano>(Clock::now() - t0).count();
}
}  // namespace

int main(int argc, char** argv) {
    const std::string dir = (argc > 1) ? argv[1] : "bench/corpus";

    std::vector<std::vector<std::string>> corpora;
    for (int n : kSizes) {
        corpora.push_back(load(dir, n));
        if (corpora.back().empty()) {
            std::println("error: empty/missing corpus n{} in {} "
                         "(run: python3 bench/gen_corpus.py)", n, dir);
            return 1;
        }
    }

    std::println("== C++: shared-corpus benchmark ==\n");
    std::println("{:<26}{:>12}{:>12}{:>12}{:>12}",
                 "strategy", "n=10", "n=100", "n=1000", "n=10000");
    std::println("{}", std::string(26 + 48, '-'));

    // Interleaved: each rep times every strategy once, round-robin, so slow
    // drift on the runner (clock, thermals, noisy neighbours) lands on all
    // strategies alike instead of on whichever ran late. Best-of-reps per cell.
    auto evs = all_evaluators();
    const double inf = std::numeric_limits<double>::infinity();
    std::vector<std::vector<double>> best(
        evs.size(), std::vector<double>(kSizes.size(), inf));
    for (std::size_t i = 0; i < kSizes.size(); ++i) {
        const auto& corpus = corpora[i];
        const int reps = (kSizes[i] <= 1000) ? 5 : 3;
        for (int r = 0; r < reps; ++r) {
            for (std::size_t k = 0; k < evs.size(); ++k) {
                const double ns = timeNs([&] {
                    double acc = 0;
                    for (const auto& e : corpus) acc += evs[k]->eval(e);
                    g_sink = acc;  // a double sink: acc is often inf/NaN, so no int cast
                });
                best[k][i] = std::min(best[k][i], ns);
            }
        }
    }

    for (std::size_t k = 0; k < evs.size(); ++k) {
        std::print("{:<26}", evs[k]->name());
        for (std::size_t i = 0; i < kSizes.size(); ++i)
            std::print("{:>12.1f}", best[k][i] / corpora[i].size() / kSizes[i]);
        std::println("");
    }
    return 0;
}
